147	            animalReader.extractDataFor(animalEntry.getKey());
148	            int numberToCreate = animalEntry.getValue();
149	            if (numberToCreate <= 0) {
150	                continue;
151	            }
152	
153	            String speciesName = animalReader.getName();
154	            addAnimalsForTemplateSpecies(speciesToPopulate, field, numberToCreate);
155	            view.setColor(speciesName, listOfColorsForAnimals.get(idxOfColorToUseNext));
156	            idxOfColorToUseNext++;
157	        }
158	    }
