239	    /**
240	     * Find an available location for an object to be created in the simulation field.
241	     * The simulation is chosen at random and is changed if the randomly selected cell
242	     * already contains an object.
243	     *
244	     * @param field (Field) The simulation's field.
245	     * @return (Location) the available location found.
246	     */
247	    private Location findAvailableLocation(Field field)
248	    {
249	        int randomWidth = rand.nextInt(DEFAULT_WIDTH);
250	        int randomDepth = rand.nextInt(DEFAULT_DEPTH);
251	        while (field.getObjectAt(randomDepth,randomWidth) != null) {
252	            randomWidth = rand.nextInt(DEFAULT_WIDTH);
253	            randomDepth = rand.nextInt(DEFAULT_DEPTH);
254	        }
255	        return new Location(randomDepth, randomWidth);
256	    }
